import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Imarisha Dada",
    short_name: "Imarisha Dada",
    description: "Empowering girls and young women in Kibera, Nairobi",
    start_url: "/",
    display: "standalone",
    background_color: "#fdf8f3",
    theme_color: "#14342a",
    // Generated by app/icon.tsx, which Next serves at `/icon`. Do not point
    // at checked-in PNGs that do not exist — that is a 404 in production.
    icons: [
      { src: "/brand/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png" },
      // Padded inside the artwork's safe zone, so the circular mark is not
      // clipped by Android's maskable circle.
      { src: "/brand/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}